 1| /**
 2|  * check-credit: the other check that runs beside the stock check.
 3|  *
 4|  * The rule: what the customer owes plus this order must stay within their
 5|  * credit limit, and this order alone must stay within their order limit.
 6|  * Example: owes 1200, limit 5000, order 2500 → 3700 ≤ 5000 and 2500 ≤ 3000 → `creditOk = true`.
 7|  */
 8| import { roundCents } from '../../money.mjs';
 9| 
10| export const purpose = 'Check the order against the credit limit and the order limit.';
11| 
12| /** @param {any} scope */
13| export function run(scope) {
14|   const c = scope.customer;
15|   const total = scope.grandTotal;
16|   const withinCredit = c.openBalance + total <= c.creditLimit;
17|   const withinOrderLimit = total <= c.orderLimit;
18|   scope.creditOk = withinCredit && withinOrderLimit;
19|   scope.headroom = roundCents(c.creditLimit - c.openBalance - total);
20| }
